import{_ as e,o as r,c as a,a2 as d}from"./chunks/framework.e4u2V5E7.js";const u=JSON.parse('{"title":"Agents","description":"Domain agents for the Ahmed Enterprise AI Workspace","frontmatter":{"title":"Agents","description":"Domain agents for the Ahmed Enterprise AI Workspace"},"headers":[],"relativePath":"agents/index.md","filePath":"agents/index.md","lastUpdated":1784485118000}'),i={name:"agents/index.md"};function n(s,t,o,l,c,g){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h1><p>The workspace uses <strong>21 agents</strong> — purpose-built AI personas that handle specific engineering domains. Each agent has defined responsibilities, tool access, and skill dependencies.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Count</th></tr></thead><tbody><tr><td>Primary agents</td><td>2</td></tr><tr><td>Domain subagents</td><td>19</td></tr><tr><td><strong>Total agents</strong></td><td><strong>21</strong></td></tr><tr><td>Read-only agents</td><td>4</td></tr></tbody></table><div class="mermaid">graph TB User([User]) --&gt; Build[build] User --&gt; Plan[plan] Build --&gt; Frontend[frontend] Build --&gt; Backend[backend] Build --&gt; Database[database] Build --&gt; Security[security] Build --&gt; Tester[tester] Build --&gt; Performance[performance] Build --&gt; DevOps[devops] Build --&gt; SEO[seo] Build --&gt; Accessibility[accessibility] Build --&gt; I18n[i18n] Build --&gt; ECommerce[ecommerce] Build --&gt; AIAgent[ai-engineer] Build --&gt; Cloud[cloud] Plan --&gt; Architect[architect] Plan --&gt; Reviewer[reviewer] Build --&gt; Designer[designer] Build --&gt; ContextEngineer[context-engineer] style Build fill:#4CAF50,color:#fff style Plan fill:#2196F3,color:#fff style Architect fill:#9C27B0,color:#fff style Reviewer fill:#9C27B0,color:#fff style Security fill:#F44336,color:#fff </div><h2 id="agent-categories" tabindex="-1">Agent Categories <a class="header-anchor" href="#agent-categories" aria-label="Permalink to &quot;Agent Categories&quot;">​</a></h2><h3 id="primary-agents" tabindex="-1">Primary Agents <a class="header-anchor" href="#primary-agents" aria-label="Permalink to &quot;Primary Agents&quot;">​</a></h3><p>The entry points for all user interactions. Every task starts with one of these agents.</p><table tabindex="0"><thead><tr><th>Agent</th><th>Role</th><th>Description</th></tr></thead><tbody><tr><td><strong>build</strong></td><td>Default</td><td>Full tool access. Executes all engineering tasks — building, editing, fixing, creating.</td></tr><tr><td><strong>plan</strong></td><td>Analysis</td><td>Read-only analysis and planning. Produces strategies without modifying files.</td></tr></tbody></table><h3 id="frontend-agents" tabindex="-1">Frontend Agents <a class="header-anchor" href="#frontend-agents" aria-label="Permalink to &quot;Frontend Agents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent</th><th>Role</th><th>Key Skills</th></tr></thead><tbody><tr><td><strong>frontend</strong></td><td>Components &amp; UI</td><td>react-patterns, nextjs-app-router, tailwind-css, responsive-design</td></tr><tr><td><strong>designer</strong></td><td>Design systems</td><td>css-motion-design, design-tokens, accessibility</td></tr></tbody></table><h3 id="backend-agents" tabindex="-1">Backend Agents <a class="header-anchor" href="#backend-agents" aria-label="Permalink to &quot;Backend Agents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent</th><th>Role</th><th>Key Skills</th></tr></thead><tbody><tr><td><strong>backend</strong></td><td>Server logic</td><td>api-design, nextjs-route-handlers, background-jobs</td></tr><tr><td><strong>api-designer</strong></td><td>API contracts</td><td>api-design, openapi-specs, versioning</td></tr></tbody></table><h3 id="database-agents" tabindex="-1">Database Agents <a class="header-anchor" href="#database-agents" aria-label="Permalink to &quot;Database Agents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent</th><th>Role</th><th>Key Skills</th></tr></thead><tbody><tr><td><strong>database</strong></td><td>Schema &amp; queries</td><td>database-design, supabase-patterns, prisma-patterns</td></tr></tbody></table><h3 id="security-agents" tabindex="-1">Security Agents <a class="header-anchor" href="#security-agents" aria-label="Permalink to &quot;Security Agents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent</th><th>Role</th><th>Key Skills</th></tr></thead><tbody><tr><td><strong>security</strong></td><td>Vulnerability assessment</td><td>security-audit, authentication-patterns, environment-secrets</td></tr></tbody></table><h3 id="quality-agents" tabindex="-1">Quality Agents <a class="header-anchor" href="#quality-agents" aria-label="Permalink to &quot;Quality Agents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent</th><th>Role</th><th>Key Skills</th></tr></thead><tbody><tr><td><strong>reviewer</strong></td><td>Code review</td><td>code-review-standards, refactoring-patterns</td></tr><tr><td><strong>tester</strong></td><td>Test creation</td><td>test-strategy, testing-patterns, coverage-analysis</td></tr><tr><td><strong>accessibility</strong></td><td>A11y audit</td><td>wcag-checklist, keyboard-navigation, screen-reader-patterns</td></tr><tr><td><strong>performance</strong></td><td>Optimization</td><td>web-performance, caching-strategies, image-optimization, bundle-optimization</td></tr></tbody></table><h3 id="architecture-agents" tabindex="-1">Architecture Agents <a class="header-anchor" href="#architecture-agents" aria-label="Permalink to &quot;Architecture Agents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent</th><th>Role</th><th>Key Skills</th></tr></thead><tbody><tr><td><strong>architect</strong></td><td>System design</td><td>architecture-patterns, refactoring-strategy, technical-debt</td></tr></tbody></table><h3 id="devops-agents" tabindex="-1">DevOps Agents <a class="header-anchor" href="#devops-agents" aria-label="Permalink to &quot;DevOps Agents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent</th><th>Role</th><th>Key Skills</th></tr></thead><tbody><tr><td><strong>devops</strong></td><td>CI/CD &amp; builds</td><td>ci-cd-pipelines, vercel-deployment, docker-patterns</td></tr><tr><td><strong>cloud</strong></td><td>Cloud architecture</td><td>serverless-patterns, cost-optimization, cloud-security</td></tr></tbody></table><h3 id="ai-agents" tabindex="-1">AI Agents <a class="header-anchor" href="#ai-agents" aria-label="Permalink to &quot;AI Agents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent</th><th>Role</th><th>Key Skills</th></tr></thead><tbody><tr><td><strong>ai-engineer</strong></td><td>LLM integration</td><td>llm-integration, rag-patterns, prompt-engineering</td></tr><tr><td><strong>context-engineer</strong></td><td>Workspace optimization</td><td>workspace-optimization, context-management</td></tr></tbody></table><h3 id="design-agents" tabindex="-1">Design Agents <a class="header-anchor" href="#design-agents" aria-label="Permalink to &quot;Design Agents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent</th><th>Role</th><th>Key Skills</th></tr></thead><tbody><tr><td><strong>designer</strong></td><td>Design systems</td><td>design-tokens, css-motion-design</td></tr></tbody></table><h3 id="i18n-agents" tabindex="-1">i18n Agents <a class="header-anchor" href="#i18n-agents" aria-label="Permalink to &quot;i18n Agents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent</th><th>Role</th><th>Key Skills</th></tr></thead><tbody><tr><td><strong>i18n</strong></td><td>Translations &amp; RTL</td><td>i18n-architecture, rtl-engineering</td></tr></tbody></table><h3 id="e-commerce-agents" tabindex="-1">E-Commerce Agents <a class="header-anchor" href="#e-commerce-agents" aria-label="Permalink to &quot;E-Commerce Agents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent</th><th>Role</th><th>Key Skills</th></tr></thead><tbody><tr><td><strong>ecommerce</strong></td><td>Product &amp; checkout</td><td>product-catalogs, checkout-flows, payment-integration</td></tr></tbody></table><h3 id="seo-agents" tabindex="-1">SEO Agents <a class="header-anchor" href="#seo-agents" aria-label="Permalink to &quot;SEO Agents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent</th><th>Role</th><th>Key Skills</th></tr></thead><tbody><tr><td><strong>seo</strong></td><td>Search optimization</td><td>technical-seo, nextjs-seo, structured-data</td></tr></tbody></table><h2 id="read-only-agents" tabindex="-1">Read-Only Agents <a class="header-anchor" href="#read-only-agents" aria-label="Permalink to &quot;Read-Only Agents&quot;">​</a></h2><p>Four agents operate in <strong>read-only mode</strong> — they analyze and advise but never modify files directly. Their output is presented to the user or passed to a build agent for execution.</p><div class="mermaid">graph LR Plan --&gt; Architect[architect 🔍] Plan --&gt; Reviewer[reviewer 🔍] Plan --&gt; Security[security 🔍] Plan --&gt; Cloud[cloud 🔍] Architect --&gt; Build[build ✏️] Reviewer --&gt; Build Security --&gt; Build Cloud --&gt; Build style Architect fill:#9C27B0,color:#fff style Reviewer fill:#9C27B0,color:#fff style Security fill:#F44336,color:#fff style Cloud fill:#FF9800,color:#fff </div><table tabindex="0"><thead><tr><th>Agent</th><th>Read-Only Scope</th><th>Why Read-Only</th></tr></thead><tbody><tr><td><strong>architect</strong></td><td>All modifications</td><td>Architecture decisions require human approval before implementation</td></tr><tr><td><strong>reviewer</strong></td><td>All modifications</td><td>Code review is advisory; authors make their own changes</td></tr><tr><td><strong>security</strong></td><td>All modifications</td><td>Security findings are reported, not silently fixed</td></tr><tr><td><strong>cloud</strong></td><td>All modifications</td><td>Cloud changes have infrastructure impact requiring explicit approval</td></tr></tbody></table><h2 id="routing-rules" tabindex="-1">Routing Rules <a class="header-anchor" href="#routing-rules" aria-label="Permalink to &quot;Routing Rules&quot;">​</a></h2><p>Agents are selected based on file paths and keyword detection.</p><h3 id="path-based-routing" tabindex="-1">Path-Based Routing <a class="header-anchor" href="#path-based-routing" aria-label="Permalink to &quot;Path-Based Routing&quot;">​</a></h3><table tabindex="0"><thead><tr><th>File Path Pattern</th><th>Primary Agent</th><th>Secondary Agents</th></tr></thead><tbody><tr><td><code>src/components/</code>, <code>*.tsx</code> with JSX</td><td>frontend</td><td>designer, accessibility</td></tr><tr><td><code>src/app/api/</code>, <code>route.ts</code></td><td>backend</td><td>api-designer, security</td></tr><tr><td><code>src/app/</code> pages</td><td>frontend</td><td>seo, i18n</td></tr><tr><td>Schema/migration files</td><td>database</td><td>architect</td></tr><tr><td><code>.github/workflows/</code></td><td>devops</td><td>security</td></tr><tr><td><code>src/app/admin/</code></td><td>frontend</td><td>backend, security</td></tr><tr><td>Translation files, <code>t()</code> calls</td><td>i18n</td><td>frontend</td></tr><tr><td><code>*.test.*</code>, <code>*.spec.*</code></td><td>tester</td><td>reviewer</td></tr><tr><td>Auth/token/security files</td><td>security</td><td>backend</td></tr><tr><td>Meta tags, <code>generateMetadata</code></td><td>seo</td><td>frontend</td></tr><tr><td>ARIA, role attributes</td><td>accessibility</td><td>frontend</td></tr></tbody></table><h3 id="keyword-based-routing" tabindex="-1">Keyword-Based Routing <a class="header-anchor" href="#keyword-based-routing" aria-label="Permalink to &quot;Keyword-Based Routing&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Keywords</th><th>Agent</th></tr></thead><tbody><tr><td>component, render, props, state, hook, CSS</td><td>frontend</td></tr><tr><td>API, endpoint, route, request, middleware</td><td>backend</td></tr><tr><td>database, schema, table, query, migration</td><td>database</td></tr><tr><td>deploy, build, CI, pipeline, Docker</td><td>devops</td></tr><tr><td>security, auth, token, permission</td><td>security</td></tr><tr><td>test, coverage, mock, assert, spec</td><td>tester</td></tr><tr><td>performance, bundle, lazy, cache, optimize</td><td>performance</td></tr><tr><td>accessibility, a11y, WCAG, ARIA</td><td>accessibility</td></tr><tr><td>SEO, meta, sitemap, ranking</td><td>seo</td></tr><tr><td>translate, i18n, RTL, Arabic, locale</td><td>i18n</td></tr><tr><td>payment, Stripe, checkout, cart</td><td>ecommerce</td></tr><tr><td>architecture, pattern, refactor, scale</td><td>architect</td></tr><tr><td>LLM, AI, prompt, embedding, vector</td><td>ai-engineer</td></tr></tbody></table><h3 id="priority-hierarchy" tabindex="-1">Priority Hierarchy <a class="header-anchor" href="#priority-hierarchy" aria-label="Permalink to &quot;Priority Hierarchy&quot;">​</a></h3><ol><li><strong>Security findings</strong> — always addressed first</li><li><strong>Build-breaking issues</strong> — fixed before feature work</li><li><strong>User explicit request</strong> — highest intent priority</li><li><strong>Primary agent domain detection</strong> — automatic routing</li><li><strong>Skill-triggered loading</strong> — on-demand context</li><li><strong>Quality recommendations</strong> — advisory</li><li><strong>Performance suggestions</strong> — advisory</li></ol><h3 id="conflict-resolution" tabindex="-1">Conflict Resolution <a class="header-anchor" href="#conflict-resolution" aria-label="Permalink to &quot;Conflict Resolution&quot;">​</a></h3><ul><li>Security overrides all other domains when there&#39;s a conflict</li><li>Accessibility wins over SEO when they conflict</li><li>Multiple agent suggestions → primary agent presents both to user</li><li>Skill overlap → load both; they complement rather than conflict</li></ul><h2 id="how-agents-work-with-skills" tabindex="-1">How Agents Work with Skills <a class="header-anchor" href="#how-agents-work-with-skills" aria-label="Permalink to &quot;How Agents Work with Skills&quot;">​</a></h2><p>Agents delegate domain knowledge to <strong>skills</strong> — focused instruction files that provide specialized workflows, code patterns, and checklists.</p><div class="mermaid">graph TD User([User Request]) --&gt; Agent[Agent] Agent --&gt; SkillLoad{Needs domain knowledge?} SkillLoad --&gt;|Yes| Skill[Skill File] Skill --&gt; Instructions[Specialized Instructions] Skill --&gt; Patterns[Code Patterns] Skill --&gt; Checklists[Quality Checklists] Instructions --&gt; Execution[Agent Executes] Patterns --&gt; Execution Checklists --&gt; Execution Execution --&gt; Result[Result] style Agent fill:#4CAF50,color:#fff style Skill fill:#2196F3,color:#fff </div><p><strong>Agent → Skill mapping:</strong></p><table tabindex="0"><thead><tr><th>Agent</th><th>Primary Skills</th></tr></thead><tbody><tr><td>build</td><td>(all skills, default entry point)</td></tr><tr><td>plan</td><td>reviewer, architect, security</td></tr><tr><td>frontend</td><td>react-patterns, nextjs-app-router, tailwind-css, responsive-design, form-engineering</td></tr><tr><td>backend</td><td>api-design, nextjs-route-handlers, background-jobs</td></tr><tr><td>database</td><td>database-design, supabase-patterns, prisma-patterns</td></tr><tr><td>security</td><td>security-audit, authentication-patterns, environment-secrets</td></tr><tr><td>reviewer</td><td>code-review-standards, refactoring-patterns</td></tr><tr><td>performance</td><td>web-performance, caching-strategies, image-optimization, bundle-optimization</td></tr><tr><td>accessibility</td><td>wcag-checklist, keyboard-navigation, screen-reader-patterns</td></tr><tr><td>seo</td><td>technical-seo, nextjs-seo</td></tr><tr><td>i18n</td><td>i18n-architecture, rtl-engineering</td></tr><tr><td>devops</td><td>ci-cd-pipelines, vercel-deployment, docker-patterns</td></tr><tr><td>architect</td><td>(reads all skills for context, no direct dependencies)</td></tr></tbody></table><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Agent definitions live in <code>~/.config/opencode/agents/</code> (global) or <code>.opencode/agents/</code> (project-specific). Each agent file specifies:</p><ul><li><strong>Name and description</strong></li><li><strong>Tool permissions</strong> (read, write, bash, search)</li><li><strong>Skill dependencies</strong></li><li><strong>Routing triggers</strong> (file patterns, keywords)</li><li><strong>Read-only flag</strong> (for advisory agents)</li></ul><p>See the <code>customize-opencode</code> skill for agent creation workflows.</p>',56)])])}const b=e(i,[["render",n]]);export{u as __pageData,b as default};
